  },
  {
   "name": "invalid lines are skipped",
   "input": "Dung;7.25\nEm;eleven\nGiang;11\n;5\nHa\nKhoa;5\n",
   "expected": "REPORT (2 students)\n1. Dung      7.25 PASS\n2. Khoa      5.00 PASS\naverage: 6.13\nskipped: 4\n-- report.txt: 5 lines\n"
  },
  {
   "h": "eyJuYW1lIjoiYSBza2lwcGVkIGxpbmUgYW5kIGEgVmlldG5hbWVzZSBuYW1lIiwiaW5wdXQiOiJ4Oy0xXG5OZ3V54buFbiDDgW5oOzlcbiIsImV4cGVjdGVkIjoiUkVQT1JUICgxIHN0dWRlbnRzKVxuMS4gTmd1eeG7hW4gw4FuaCAgOS4wMCBQQVNTXG5hdmVyYWdlOiA5LjAwXG5za2lwcGVkOiAxXG4tLSByZXBvcnQudHh0OiA0IGxpbmVzXG4ifQ=="
  },
  {
   "h": "eyJuYW1lIjoibm9ib2R5IHZhbGlkIiwiaW5wdXQiOiJMYW47LTAuNVxuIiwiZXhwZWN0ZWQiOiJSRVBPUlQgKDAgc3R1ZGVudHMpXG5hdmVyYWdlOiAwLjAwXG5za2lwcGVkOiAxXG4tLSByZXBvcnQudHh0OiAzIGxpbmVzXG4ifQ=="
  }
